/// <summary>
/// MPJ_19962_MDRPOTransactionalMissingFields kavya 25/3/2022
/// The <t>PurchTable</t> table extension
/// </summary>
[ExtensionOf(dataentityviewstr(PurchPurchaseOrderConfirmationLineEntity))]
final class METPurchPurchaseOrderConfirmationLineEntity_Extension
{
}

Method.Source:
    /// <summary>
    /// Added by kavya on 11/5/2022 for MPJ_19962_MDRPOTransactionalMissingFields - part 2
    /// Map data fields to virtual fields
    /// </summary>
    public void postLoad()
    {
        MetItemSiteSettingsSetup    ItemSiteSettingsSetup;

        select firstonly1 TempRcvLimit from ItemSiteSettingsSetup
            where ((ItemSiteSettingsSetup.ItemId == this.ItemNumber && ItemSiteSettingsSetup.InventSiteId == this.ReceivingSiteId)
                || ItemSiteSettingsSetup.ItemId == this.ItemNumber)
                && ItemSiteSettingsSetup.TempRcvLimit != 0;

        this.METPOLineTempRcvLimit = ItemSiteSettingsSetup.TempRcvLimit? ItemSiteSettingsSetup.TempRcvLimit: InventTable::find(this.ItemNumber).PdsBestBefore;

        next postload();
    }

    /// <summary>
    /// getPOLineCartonPerLayer method COC
    /// </summary>
    /// <returns> string value</returns>
    private static server str getPOLineCartonPerLayer()
    {
        str CartonPerLayer;
        SysDictTable      dictMetItemSiteSettingsSetup = new SysDictTable(tableNum(MetItemSiteSettingsSetup));
        str itemid;
        str siteid;

        itemid = SysComputedColumn::returnField(dataentityviewstr(PurchPurchaseOrderConfirmationLineEntity), dataEntityDataSourceStr(PurchPurchaseOrderConfirmationLineEntity, PurchLineAllVersions),
            fieldStr(PurchLineAllVersions, itemid));

        siteid = SysComputedColumn::returnField(dataentityviewstr(PurchPurchaseOrderConfirmationLineEntity), dataEntityDataSourceStr(PurchPurchaseOrderConfirmationLineEntity, InventDim),
            fieldStr(InventDim, InventSiteId));


        CartonPerLayer = strFmt(@"@MET:METSQLQuery1",
            dictMetItemSiteSettingsSetup.fieldName(fieldNum(MetItemSiteSettingsSetup, CartonPerLayer), DbBackend::Sql),
            dictMetItemSiteSettingsSetup.name(DbBackend::Sql),
            dictMetItemSiteSettingsSetup.fieldName(fieldNum(MetItemSiteSettingsSetup, ItemId), DbBackend::Sql),
            itemid,
            dictMetItemSiteSettingsSetup.fieldName(fieldNum(MetItemSiteSettingsSetup, InventSiteId), DbBackend::Sql),
            siteid);

        return CartonPerLayer;
    }

