    /// <summary>
    /// getPOLineConfInventoryQty method COC
    /// </summary>
    /// <returns> string value</returns>
    private static server str getPOLineConfInventoryQty()
    {
        str                 InventoryQty;
        SysDictTable        dictPurchLine = new SysDictTable(tableNum(PurchLine));
        str                 itemid;
        str                 lineNum;
        str                 purchId;

        purchId = SysComputedColumn::returnField(dataentityviewstr(PurchPurchaseOrderConfirmationLineEntity), dataEntityDataSourceStr(PurchPurchaseOrderConfirmationLineEntity, PurchLineAllVersions),
            fieldStr(PurchLineAllVersions, purchId));

        itemid = SysComputedColumn::returnField(dataentityviewstr(PurchPurchaseOrderConfirmationLineEntity), dataEntityDataSourceStr(PurchPurchaseOrderConfirmationLineEntity, PurchLineAllVersions),
            fieldStr(PurchLineAllVersions, itemid));

        lineNum = SysComputedColumn::returnField(dataentityviewstr(PurchPurchaseOrderConfirmationLineEntity), dataEntityDataSourceStr(PurchPurchaseOrderConfirmationLineEntity, PurchLineAllVersions),
            fieldStr(PurchLineAllVersions, lineNumber));


        InventoryQty = strFmt(@"@MET:METSQLQuery2",
            dictPurchLine.fieldName(fieldNum(PurchLine, QtyOrdered), DbBackend::Sql),
            dictPurchLine.name(DbBackend::Sql),
            dictPurchLine.fieldName(fieldNum(PurchLine, purchId), DbBackend::Sql),
            purchId,
            dictPurchLine.fieldName(fieldNum(PurchLine, ItemId), DbBackend::Sql),
            itemid,
            dictPurchLine.fieldName(fieldNum(PurchLine, lineNumber), DbBackend::Sql),
            lineNum);

        return InventoryQty;
    }

